<script setup lang="ts">
definePageMeta({layout:'workspace'})
const db=useSupabaseClient()
const {platformAdmin,schoolId,load:reloadSchools}=useSchool()
type School={id:string;name:string;code:string|null;allow_student_self_registration:boolean;deactivated_at:string|null;created_at:string}
type Request={id:string;school_name:string;school_domain:string;contact_name:string;contact_email:string;contact_position:string;status:string;created_at:string;requester_id:string|null;created_school_id:string|null}
const tab=ref('schools'),schools=ref<School[]>([]),requests=ref<Request[]>([]),search=ref(''),statusFilter=ref('all'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const selectedId=ref(''),name=ref(''),code=ref(''),selfRegistration=ref(false),domains=ref<{domain:string;is_primary:boolean;is_verified:boolean}[]>([])
const selected=computed(()=>schools.value.find(s=>s.id===selectedId.value))
const filteredSchools=computed(()=>schools.value.filter(s=>(s.name+' '+(s.code||'')).toLowerCase().includes(search.value.toLowerCase())))
const filteredRequests=computed(()=>requests.value.filter(r=>statusFilter.value==='all'||r.status===statusFilter.value))
function choose(s:School){selectedId.value=s.id;name.value=s.name;code.value=s.code||'';selfRegistration.value=s.allow_student_self_registration;tab.value='settings';void loadDomains()}
async function loadDomains(){domains.value=[];if(!selectedId.value)return;const r=await db.from('school_email_domains').select('domain,is_primary,is_verified').eq('school_id',selectedId.value).order('domain');if(r.error)error.value=r.error.message;else domains.value=r.data||[]}
async function load(){if(!platformAdmin.value)return;loading.value=true;error.value='';try{const [s,r]=await Promise.all([db.from('schools').select('id,name,code,allow_student_self_registration,deactivated_at,created_at').order('name'),db.from('school_requests').select('id,school_name,school_domain,contact_name,contact_email,contact_position,status,created_at,requester_id,created_school_id').order('created_at',{ascending:false})]);if(s.error)throw s.error;if(r.error)throw r.error;schools.value=s.data||[];requests.value=r.data||[];if(selectedId.value){const updated=schools.value.find(s=>s.id===selectedId.value);if(updated){name.value=updated.name;code.value=updated.code||'';selfRegistration.value=updated.allow_student_self_registration}}}catch(e:any){error.value=e.message||'Unable to load schools'}finally{loading.value=false}}
async function save(){if(!platformAdmin.value||!selectedId.value||busy.value)return;if(!confirm('Save changes to this school?'))return;busy.value=true;error.value='';notice.value='';try{const r=await db.rpc('update_school_settings',{p_school_id:selectedId.value,p_name:name.value,p_code:code.value,p_allow_student_registration:selfRegistration.value});if(r.error)throw r.error;await load();await reloadSchools();notice.value='School settings saved'}catch(e:any){error.value=e.message||'Unable to save school'}finally{busy.value=false}}
async function review(r:Request,approve:boolean){if(!platformAdmin.value||busy.value)return;if(approve&&!r.requester_id){error.value='This public enquiry has no registered requester. It requires a separate administrator invitation workflow before approval; no school has been created.';return}if(!confirm((approve?'Approve':'Reject')+' school request for '+r.school_name+'?'))return;busy.value=true;error.value='';notice.value='';try{const result=await db.rpc('review_school_request',{p_request_id:r.id,p_approve:approve,p_review_notes:null});if(result.error)throw result.error;await load();await reloadSchools();notice.value=approve?'School approved and created. Review the initial administrator membership.':'School request rejected'}catch(e:any){error.value=e.message||'Unable to review request'}finally{busy.value=false}}
watch(platformAdmin,()=>{void load()},{immediate:true})
</script>
<template><div class="space-y-6"><div><h1 class="text-2xl font-bold">Schools</h1><p class="text-sm text-[var(--muted)]">Platform administration · Registered schools, onboarding requests and settings</p></div><UiPanel v-if="!platformAdmin">Platform Administrator access is required.</UiPanel><template v-else><div class="flex flex-wrap gap-2"><button v-for="t in [{id:'schools',label:'All Schools'},{id:'requests',label:'School Requests'},{id:'settings',label:'School Settings'}]" :key="t.id" class="rounded-xl border border-[var(--border)] px-4 py-2 text-sm font-semibold" :class="tab===t.id?'bg-blue-600 text-white':''" @click="tab=t.id">{{t.label}}<span v-if="t.id==='requests'"> ({{requests.filter(r=>r.status==='pending').length}})</span></button></div><p v-if="error" class="text-red-600" role="alert">{{error}}</p><p v-if="notice" class="text-green-600" role="status">{{notice}}</p><p v-if="loading">Loading schools…</p><UiPanel v-if="tab==='schools'"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 class="text-lg font-bold">Registered schools ({{schools.length}})</h2><input v-model="search" placeholder="Search schools" aria-label="Search schools" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></div><div v-for="s in filteredSchools" :key="s.id" class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border)] py-4"><div><p class="font-semibold">{{s.name}}</p><p class="text-sm text-[var(--muted)]">{{s.code||'No code'}} · {{s.deactivated_at?'Inactive':'Active'}}</p></div><button class="rounded-lg border border-[var(--border)] px-4 py-2 text-sm" @click="choose(s)">View / Edit</button></div><p v-if="!filteredSchools.length" class="text-sm text-[var(--muted)]">No matching schools.</p></UiPanel><UiPanel v-else-if="tab==='requests'"><div class="mb-4 flex flex-wrap justify-between gap-3"><h2 class="text-lg font-bold">School registration requests</h2><select v-model="statusFilter" aria-label="Request status" class="rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"><option value="all">All statuses</option><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></div><div v-for="r in filteredRequests" :key="r.id" class="border-b border-[var(--border)] py-4"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="font-semibold">{{r.school_name}}</p><p class="text-sm text-[var(--muted)]">{{r.school_domain}} · {{r.contact_name}} ({{r.contact_position}}) · {{r.contact_email}}</p><p class="mt-1 text-sm">Status: {{r.status}} <span v-if="r.status==='pending'&&!r.requester_id">· Public enquiry – requires administrator onboarding</span></p></div><div v-if="r.status==='pending'" class="flex gap-2"><button :disabled="busy||!r.requester_id" :title="!r.requester_id?'No registered requester: manual onboarding required':''" class="rounded-lg bg-blue-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-40" @click="review(r,true)">Approve</button><button :disabled="busy" class="rounded-lg border border-[var(--border)] px-4 py-2 text-sm" @click="review(r,false)">Reject</button></div></div></div><p v-if="!filteredRequests.length" class="text-sm text-[var(--muted)]">No requests found.</p></UiPanel><UiPanel v-else><h2 class="mb-4 text-lg font-bold">School Settings</h2><label class="block max-w-xl text-sm font-semibold">Select school<select v-model="selectedId" class="mt-2 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3" @change="selected&&choose(selected)"><option value="">Choose a school</option><option v-for="s in schools" :key="s.id" :value="s.id">{{s.name}}</option></select></label><form v-if="selected" class="mt-6 max-w-xl space-y-5" @submit.prevent="save"><p class="text-sm text-[var(--muted)]">Status: {{selected.deactivated_at?'Inactive':'Active'}}</p><label class="block text-sm font-semibold">School name<input v-model="name" required minlength="2" maxlength="160" class="mt-2 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></label><label class="block text-sm font-semibold">School code<input v-model="code" maxlength="30" class="mt-2 w-full rounded-lg border border-[var(--border)] bg-[var(--surface)] p-3"/></label><button :disabled="busy||!!selected.deactivated_at" class="rounded-lg bg-blue-600 px-5 py-3 font-semibold text-white disabled:opacity-50">Save school settings</button><h3 class="pt-4 font-bold">Email domains</h3><p class="text-sm text-[var(--muted)]">Domain verification is read-only until its dedicated workflow is implemented.</p><div v-for="d in domains" :key="d.domain" class="border-b border-[var(--border)] py-2 text-sm">{{d.domain}} · {{d.is_verified?'Verified':'Unverified'}}{{d.is_primary?' · Primary':''}}</div></form></UiPanel></template></div></template>